operator_asks_delivery_provenance_trg.function_def:
CREATE OR REPLACE FUNCTION public.operator_asks_delivery_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.delivered_at IS NOT NULL AND NEW.delivered_source IS NULL THEN
    NEW.delivered_source := 'manual';
  END IF;
  RETURN NEW;
END;
$function$

work_item_mirror_ask_delete_trg.function_def:
CREATE OR REPLACE FUNCTION public.work_item_mirror_ask_delete_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    BEGIN
        PERFORM work_item_mark_source_deleted('operator_asks', OLD.id, 'trigger:operator_asks:deleted');
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'work_item drop-mirror failed for operator_asks id=%: %', OLD.id, SQLERRM;
    END;
    RETURN OLD;
END;
$function$
